-- Real SQL roles and native create/get/submit/start functions; no provider execution.
CREATE FUNCTION public.test_create_work(t uuid,a uuid,k text,c text,i uuid DEFAULT gen_random_uuid()) RETURNS uuid LANGUAGE sql SECURITY INVOKER AS $$
 SELECT work_id FROM public.create_paige_durable_work(t,a,i,NULL,c,k,jsonb_build_object('tenant_id',t,'actor_user_id',a),'test-scope',300,5)$$;
CREATE TABLE public.test_work(name text PRIMARY KEY,id uuid);
GRANT ALL ON public.test_work TO authenticated,service_role;
SELECT set_config('test.actor','10000000-0000-0000-0000-000000000001',false);
SET ROLE authenticated;
SELECT public.test_denied($q$SELECT public.knowledge_actor_authorized(NULL,NULL)$q$,'permission denied');
SELECT public.test_denied($q$SELECT public.test_create_work('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','knowledge_extract','knowledge.extract')$q$,'permission denied');
RESET ROLE;
SET ROLE anon;
SELECT public.test_denied($q$SELECT public.knowledge_actor_authorized(NULL,NULL)$q$,'permission denied');
SELECT public.test_denied($q$SELECT public.get_paige_durable_work(NULL)$q$,'permission denied');
RESET ROLE;
SET ROLE service_role;
SELECT public.test_assert(public.knowledge_actor_authorized('10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000003'),'company operator authority');
SELECT public.test_assert(NOT public.knowledge_actor_authorized('10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000004'),'operator other company selection refused');
SELECT public.test_assert(NOT public.knowledge_actor_authorized(NULL,'00000000-0000-0000-0000-000000000003'),'null actor refused');
INSERT INTO public.test_work SELECT 'member',public.test_create_work('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','knowledge_extract','knowledge.extract');
INSERT INTO public.test_work SELECT 'operator',public.test_create_work('00000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000002','knowledge_publish','knowledge.publish');
INSERT INTO public.test_work SELECT 'owner',public.test_create_work('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000003','knowledge_publish','knowledge.publish');
SELECT public.test_assert((SELECT count(*)=3 FROM public.test_work),'member/operator/owner can create exact pairs');
SELECT public.test_denied($q$SELECT public.test_create_work('00000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000002','document_authoring','document_generate')$q$,'DURABLE_WORK_INITIATOR_FORBIDDEN');
SELECT public.test_denied($q$SELECT public.test_create_work('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','knowledge_extract','document_generate')$q$,'DURABLE_WORK_KNOWLEDGE_KIND_INVALID');
SELECT public.test_denied($q$SELECT public.test_create_work('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','document_authoring','knowledge.extract')$q$,'DURABLE_WORK_KNOWLEDGE_KIND_INVALID');
SELECT public.test_denied($q$SELECT public.test_create_work('00000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000002','knowledge_other','knowledge.other')$q$,'DURABLE_WORK_INITIATOR_FORBIDDEN');
SELECT public.test_denied($q$SELECT public.test_create_work('00000000-0000-0000-0000-000000000004','10000000-0000-0000-0000-000000000002','knowledge_extract','knowledge.extract')$q$,'DURABLE_WORK_INITIATOR_FORBIDDEN');
SELECT public.test_denied($q$SELECT public.test_create_work('00000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000001','knowledge_extract','knowledge.extract')$q$,'DURABLE_WORK_INITIATOR_FORBIDDEN');
RESET ROLE;
-- Public status is scoped to current caller, not an actor supplied as an argument.
SET ROLE authenticated;
SELECT public.test_assert((SELECT count(*)=1 FROM public.get_paige_durable_work((SELECT id FROM public.test_work WHERE name='member'))),'initiator status visible');
SELECT set_config('test.actor','10000000-0000-0000-0000-000000000004',false);
SELECT public.test_assert((SELECT count(*)=0 FROM public.get_paige_durable_work((SELECT id FROM public.test_work WHERE name='member'))),'ordinary member cannot read another member work');
RESET ROLE;
UPDATE public.tenant_members SET is_owner=true WHERE user_id='10000000-0000-0000-0000-000000000004';
SET ROLE authenticated;
SELECT public.test_assert((SELECT count(*)=1 FROM public.get_paige_durable_work((SELECT id FROM public.test_work WHERE name='member'))),'active member owner flag can read another member Knowledge work');
RESET ROLE;
UPDATE public.tenant_members SET status='inactive' WHERE user_id='10000000-0000-0000-0000-000000000004';
SET ROLE authenticated;
SELECT public.test_assert((SELECT count(*)=0 FROM public.get_paige_durable_work((SELECT id FROM public.test_work WHERE name='member'))),'inactive owner flag cannot read Knowledge work');
RESET ROLE;
UPDATE public.tenant_members SET status='active',is_owner=false WHERE user_id='10000000-0000-0000-0000-000000000004';
SET ROLE authenticated;
SELECT public.test_assert((SELECT count(*)=0 FROM public.get_paige_durable_work((SELECT id FROM public.test_work WHERE name='member'))),'ordinary member without owner flag still refused');
RESET ROLE;
UPDATE public.tenant_members SET role='admin' WHERE user_id='10000000-0000-0000-0000-000000000004';
SET ROLE authenticated;
SELECT public.test_assert((SELECT count(*)=1 FROM public.get_paige_durable_work((SELECT id FROM public.test_work WHERE name='member'))),'tenant admin can read workspace work');
SELECT set_config('test.actor','10000000-0000-0000-0000-000000000002',false);
SELECT public.test_assert((SELECT count(*)=1 FROM public.get_paige_durable_work((SELECT id FROM public.test_work WHERE name='operator'))),'operator status without membership');
RESET ROLE;
UPDATE public.profiles SET active_tenant_id='00000000-0000-0000-0000-000000000001' WHERE user_id='10000000-0000-0000-0000-000000000002';
SET ROLE service_role;
SELECT public.test_assert(NOT public.knowledge_actor_authorized('10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000001'),'operator customer workspace without membership refused');
RESET ROLE;
SET ROLE authenticated;
SELECT public.test_assert((SELECT count(*)=0 FROM public.get_paige_durable_work((SELECT id FROM public.test_work WHERE name='operator'))),'status hidden after selection switch');
RESET ROLE;
UPDATE public.profiles SET active_tenant_id='00000000-0000-0000-0000-000000000003' WHERE user_id='10000000-0000-0000-0000-000000000002';
DELETE FROM public.user_roles WHERE user_id='10000000-0000-0000-0000-000000000002';
SET ROLE authenticated;
SELECT public.test_assert((SELECT count(*)=0 FROM public.get_paige_durable_work((SELECT id FROM public.test_work WHERE name='operator'))),'operator revocation hides work');
RESET ROLE;
UPDATE public.profiles SET active_tenant_id=NULL WHERE user_id='10000000-0000-0000-0000-000000000003';
SET ROLE service_role;
SELECT public.test_assert(NOT public.knowledge_actor_authorized('10000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000001'),'owner still requires selected workspace');
RESET ROLE;
SELECT set_config('test.actor','10000000-0000-0000-0000-000000000003',false);
SET ROLE authenticated;
SELECT public.test_assert((SELECT count(*)=0 FROM public.get_paige_durable_work((SELECT id FROM public.test_work WHERE name='member'))),'owner status requires selected workspace');
RESET ROLE;
UPDATE public.tenant_members SET status='inactive' WHERE user_id='10000000-0000-0000-0000-000000000001';
SET ROLE service_role;
SELECT public.test_assert(NOT public.knowledge_actor_authorized('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001'),'inactive membership refused');
SELECT public.test_denied($q$SELECT public.test_create_work('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','knowledge_extract','knowledge.extract')$q$,'DURABLE_WORK_INITIATOR_FORBIDDEN');
RESET ROLE;
UPDATE public.tenant_members SET status='active' WHERE user_id='10000000-0000-0000-0000-000000000001';
UPDATE auth.users SET banned_until=now()+interval '1 day' WHERE id='10000000-0000-0000-0000-000000000001';
SET ROLE service_role;
SELECT public.test_assert(NOT public.knowledge_actor_authorized('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001'),'banned actor refused');
SELECT public.test_denied($q$SELECT public.test_create_work('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','knowledge_extract','knowledge.extract')$q$,'DURABLE_WORK_INITIATOR_FORBIDDEN');
-- Existing generic work policy is intentionally unchanged by the new actor check.
INSERT INTO public.test_work SELECT 'legacy',public.test_create_work('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','document_authoring','document_generate');
RESET ROLE;
UPDATE auth.users SET banned_until=NULL,deleted_at=now() WHERE id='10000000-0000-0000-0000-000000000001';
SET ROLE service_role;
SELECT public.test_assert(NOT public.knowledge_actor_authorized('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001'),'deleted actor refused');
RESET ROLE;
UPDATE auth.users SET deleted_at=NULL WHERE id='10000000-0000-0000-0000-000000000001';
UPDATE public.tenants SET status='inactive' WHERE id='00000000-0000-0000-0000-000000000001';
SET ROLE service_role;
SELECT public.test_assert(NOT public.knowledge_actor_authorized('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001'),'inactive tenant refused');
RESET ROLE;
UPDATE public.tenants SET status='active' WHERE id='00000000-0000-0000-0000-000000000001';
-- Actual old document-authoring submit/start still executes through native functions.
SELECT set_config('test.actor','10000000-0000-0000-0000-000000000001',false);
SET ROLE authenticated;
INSERT INTO public.test_work SELECT 'document',work_id FROM public.submit_paige_document_work('60000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','{"version":1,"doc_type":"guide","title":"Test guide","brief":"Write a neutral test guide."}');
SELECT public.test_assert((SELECT resumed_existing FROM public.submit_paige_document_work('60000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','{"version":1,"doc_type":"guide","title":"Test guide","brief":"Write a neutral test guide."}')),'old document submission replay unchanged');
SELECT public.test_assert((SELECT count(*)=1 FROM public.get_paige_durable_work((SELECT id FROM public.test_work WHERE name='document'))),'old document status visible');
RESET ROLE;
SET ROLE service_role;
SELECT public.test_assert((SELECT work_status='claimed' AND attempt_count=1 FROM public.start_paige_document_work_execution((SELECT id FROM public.test_work WHERE name='document'))),'old document dispatch works');
SELECT public.test_denied(format('SELECT public.start_paige_document_work_execution(%L)',(SELECT id FROM public.test_work WHERE name='document')),'DURABLE_WORK_ALREADY_DISPATCHED');
SELECT public.test_denied(format('SELECT public.start_paige_document_work_execution(%L)',(SELECT id FROM public.test_work WHERE name='member')),'DURABLE_WORK_NOT_FOUND');
RESET ROLE;
SELECT set_config('test.actor','10000000-0000-0000-0000-000000000003',false);
SET ROLE authenticated;
SELECT public.test_assert((SELECT count(*)=1 FROM public.get_paige_durable_work((SELECT id FROM public.test_work WHERE name='document'))),'old owner status policy unchanged without selection');
RESET ROLE;
SELECT public.test_denied($q$UPDATE public.tenant_knowledge_docs SET record_state='draft',content='' WHERE title='A'$q$,'KNOWLEDGE_LIFECYCLE_UNAVAILABLE');
SELECT public.test_assert((SELECT count(*)=5 FROM public.paige_durable_work),'one native envelope only and failed creates absent');

-- An inactive literal company membership does not remove independent operator authority.
INSERT INTO public.user_roles VALUES('10000000-0000-0000-0000-000000000002','platform_admin');
INSERT INTO public.tenant_members VALUES('00000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000002','inactive','member',false);
SET ROLE service_role;
SELECT public.test_assert(public.knowledge_actor_authorized('10000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000003'),'canonical independent operator authority preserved with inactive membership');
SELECT public.test_assert(NOT public.knowledge_actor_authorized('10000000-0000-0000-0000-000000000009','00000000-0000-0000-0000-000000000001'),'nonexistent actor refused');
SELECT public.test_denied($q$SELECT public.create_paige_durable_work('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001',gen_random_uuid(),NULL,'knowledge.extract','knowledge_extract','{"tenant_id":"00000000-0000-0000-0000-000000000002","actor_user_id":"10000000-0000-0000-0000-000000000001"}','test')$q$,'DURABLE_WORK_AUTHORITY_CONTEXT_INVALID');
SELECT public.test_denied($q$SELECT public.create_paige_durable_work('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000003',gen_random_uuid(),'50000000-0000-0000-0000-000000000001','knowledge.extract','knowledge_extract','{"tenant_id":"00000000-0000-0000-0000-000000000001","actor_user_id":"10000000-0000-0000-0000-000000000003"}','test')$q$,'DURABLE_WORK_INITIATOR_FORBIDDEN');
RESET ROLE;
UPDATE public.profiles SET active_tenant_id='00000000-0000-0000-0000-000000000001' WHERE user_id='10000000-0000-0000-0000-000000000003';
SET ROLE service_role;
SELECT public.test_denied($q$SELECT public.create_paige_durable_work('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000003',gen_random_uuid(),'50000000-0000-0000-0000-000000000001','knowledge.extract','knowledge_extract','{"tenant_id":"00000000-0000-0000-0000-000000000001","actor_user_id":"10000000-0000-0000-0000-000000000003"}','test')$q$,'DURABLE_WORK_THREAD_FORBIDDEN');
SELECT public.test_create_work('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','knowledge_extract','knowledge.extract','60000000-0000-0000-0000-000000000009');
SELECT public.test_assert((SELECT resumed_existing FROM public.create_paige_durable_work('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','60000000-0000-0000-0000-000000000009',NULL,'knowledge.extract','knowledge_extract','{"tenant_id":"00000000-0000-0000-0000-000000000001","actor_user_id":"10000000-0000-0000-0000-000000000001"}','test-scope',300,5)),'Knowledge intent replay remains one envelope');
SELECT public.test_denied($q$SELECT public.test_create_work('00000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','knowledge_publish','knowledge.publish','60000000-0000-0000-0000-000000000009')$q$,'DURABLE_WORK_INTENT_REPLAY_MISMATCH');
RESET ROLE;
